palette = {"orange": "#E69F00", "sky": "#56B4E9", "green": "#009E73", "blue": "#0072B2", "red": "#D55E00", "pink": "#CC79A7"}


def too_similar(palette, min_gap):
    names = sorted(palette)
    pairs = []
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            if abs(luminance(palette[a]) - luminance(palette[b])) < min_gap:
                pairs.append((a, b))
    return sorted(pairs)


print(too_similar(palette, 0.1))
